import { Component, OnInit } from '@angular/core';
import { MisComprasService } from 'src/app/services/mis-compras.service';
import { UsuarioService } from 'src/app/services/usuario.service';

@Component({
  selector: 'app-ejercicio42',
  templateUrl: './ejercicio42.component.html',
  styleUrls: ['./ejercicio42.component.css']
})
export class Ejercicio42Component implements OnInit{

  clientes: any[] = [];

  constructor(public miscomprasService: MisComprasService, public usuarioService: UsuarioService){}

  ngOnInit(): void {

    this.miscomprasService.obtenerCompras().subscribe( compras => {

      const productoMasCaro = this
    });

  }



  //metodo encontrarProductoMasCaro
  encontrarProductoMasCaro(compras: any[]): any {
    let maxPrecio = 0;
    let productoMasCaro = null;
    compras.forEach(compra => {
      compra.productos.forEach(producto => {
        if (producto.precio > maxPrecio) {
          maxPrecio = producto.precio;
          productoMasCaro = producto;
        }
      });
    });
    return productoMasCaro;
  }

}
